import * as React from "react";

import { cn } from "../lib/utils";

import detailStyles from "./detail-layout.module.css";
import styles from "./text.module.css";

export function PageMeasure({
  className,
  ref,
  ...props
}: React.ComponentPropsWithoutRef<"div"> & { ref?: React.Ref<HTMLDivElement> }) {
  return (
    <div
      ref={ref}
      data-slot="page-measure"
      className={cn(styles.measurePage, className)}
      {...props}
    />
  );
}
PageMeasure.displayName = "PageMeasure";
export function FormMeasure({
  className,
  ref,
  ...props
}: React.ComponentPropsWithoutRef<"div"> & { ref?: React.Ref<HTMLDivElement> }) {
  return (
    <div
      ref={ref}
      data-slot="form-measure"
      className={cn(styles.measureForm, className)}
      {...props}
    />
  );
}
FormMeasure.displayName = "FormMeasure";

export type LayoutGap = 0 | 2 | 4 | 6 | 8 | 12 | 16 | 20 | 24 | 32 | 48;
type LayoutProps = React.ComponentPropsWithoutRef<"div"> & {
  gap?: LayoutGap;
  align?: "start" | "center" | "end" | "stretch";
  justify?: "start" | "center" | "end" | "between";
};
const spacing = (gap: LayoutGap) => (gap === 0 ? 0 : `var(--v4-space-${gap})`);
const alignment = (align: LayoutProps["align"] | "baseline") =>
  align === "start" ? "flex-start" : align === "end" ? "flex-end" : align;
export function Stack({
  gap = 16,
  align = "stretch",
  justify = "start",
  style,
  className,
  ref,
  ...props
}: LayoutProps & { ref?: React.Ref<HTMLDivElement> }) {
  return (
    <div
      ref={ref}
      data-slot="stack"
      className={cn(styles.stack, className)}
      style={{
        gap: spacing(gap),
        alignItems: alignment(align),
        justifyContent: justify === "between" ? "space-between" : alignment(justify),
        ...style
      }}
      {...props}
    />
  );
}
Stack.displayName = "Stack";
export function Inline({
  gap = 8,
  align = "center",
  justify = "start",
  wrap = true,
  style,
  className,
  ref,
  ...props
}: Omit<LayoutProps, "align"> & {
  align?: LayoutProps["align"] | "baseline";
  wrap?: boolean;
} & { ref?: React.Ref<HTMLDivElement> }) {
  return (
    <div
      ref={ref}
      data-slot="inline"
      className={cn(styles.inline, className)}
      style={{
        gap: spacing(gap),
        alignItems: alignment(align),
        justifyContent: justify === "between" ? "space-between" : alignment(justify),
        flexWrap: wrap ? "wrap" : "nowrap",
        ...style
      }}
      {...props}
    />
  );
}
Inline.displayName = "Inline";
export function Grid({
  gap = 16,
  columns,
  min = "tile",
  style,
  className,
  ref,
  ...props
}: Omit<LayoutProps, "align" | "justify"> & {
  columns?: 2 | 3 | 4 | "1:2";
  min?: "tile" | "card";
} & {
  ref?: React.Ref<HTMLDivElement>;
}) {
  let gridTemplateColumns = `repeat(auto-fit, minmax(min(100%, var(--v4-size-${min}-min)), 1fr))`;
  if (columns === "1:2") gridTemplateColumns = "minmax(0, 1fr) minmax(0, 2fr)";
  else if (columns) gridTemplateColumns = `repeat(${columns}, minmax(0, 1fr))`;
  return (
    <div
      ref={ref}
      data-slot="grid"
      data-columns={columns}
      className={cn(styles.grid, columns === "1:2" && styles.gridSplit, className)}
      style={{
        gap: spacing(gap),
        gridTemplateColumns,
        ...style
      }}
      {...props}
    />
  );
}
Grid.displayName = "Grid";
export function Container({
  className,
  ref,
  ...props
}: React.ComponentPropsWithoutRef<"div"> & { ref?: React.Ref<HTMLDivElement> }) {
  return (
    <div ref={ref} data-slot="container" className={cn(styles.container, className)} {...props} />
  );
}
Container.displayName = "Container";
export function Measure({
  size = "prose",
  className,
  ref,
  ...props
}: React.ComponentPropsWithoutRef<"div"> & { size?: "page" | "form" | "prose" } & {
  ref?: React.Ref<HTMLDivElement>;
}) {
  return (
    <div
      ref={ref}
      data-slot="measure"
      data-size={size}
      className={cn(
        size === "page"
          ? styles.measurePage
          : size === "form"
            ? styles.measureForm
            : styles.measureProse,
        className
      )}
      {...props}
    />
  );
}
Measure.displayName = "Measure";

const scrollParent = (node: HTMLElement) => {
  for (let parent = node.parentElement; parent; parent = parent.parentElement) {
    if (/(auto|scroll|overlay)/.test(getComputedStyle(parent).overflowY)) return parent;
  }
  return null;
};

export function DetailLayout({
  aside,
  asideLabel,
  children,
  className,
  ref,
  ...props
}: React.ComponentPropsWithoutRef<"div"> & {
  aside: React.ReactNode;
  asideLabel: string;
  ref?: React.Ref<HTMLDivElement>;
}) {
  const asideRef = React.useRef<HTMLElement>(null);
  const [fits, setFits] = React.useState(false);
  React.useLayoutEffect(() => {
    const node = asideRef.current;
    if (!node) return undefined;
    const scroller = scrollParent(node);
    const measure = () => {
      const style = getComputedStyle(node);
      const room =
        (scroller ? scroller.clientHeight : window.innerHeight) -
        (parseFloat(style.scrollMarginTop) || 0) -
        (parseFloat(style.scrollMarginBottom) || 0);
      setFits(node.offsetHeight <= room);
    };
    measure();
    window.addEventListener("resize", measure);
    if (typeof ResizeObserver === "undefined")
      return () => window.removeEventListener("resize", measure);
    const observer = new ResizeObserver(measure);
    observer.observe(node);
    if (scroller) observer.observe(scroller);
    return () => {
      observer.disconnect();
      window.removeEventListener("resize", measure);
    };
  }, []);
  return (
    <div
      ref={ref}
      data-slot="detail-layout"
      className={cn(detailStyles.root, className)}
      {...props}
    >
      <div className={detailStyles.columns}>
        <aside
          ref={asideRef}
          data-slot="detail-layout-aside"
          data-sticky={fits || undefined}
          aria-label={asideLabel}
          className={detailStyles.aside}
        >
          {aside}
        </aside>
        <div data-slot="detail-layout-main" className={detailStyles.main}>
          {children}
        </div>
      </div>
    </div>
  );
}
DetailLayout.displayName = "DetailLayout";

.root {
  --v4-detail-layout-offset: var(--v4-space-24);
  container: detail-layout / inline-size;
  min-width: 0;
}
.columns {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  align-items: start;
  gap: var(--v4-space-24);
}
.aside,
.main {
  display: flex;
  flex-direction: column;
  gap: var(--v4-space-24);
  min-width: 0;
}
.aside {
  scroll-margin-top: var(--v4-detail-layout-offset);
  scroll-margin-bottom: var(--v4-space-24);
}
/* Container conditions cannot read custom properties, so this repeats size-sidecar-collapse (896px); detail-layout.test.ts fails if they drift. */
@container detail-layout (min-width: 896px) {
  .columns {
    grid-template-columns: minmax(0, 1fr) var(--v4-size-sidecar);
    grid-template-areas: "main aside";
  }
  .aside {
    grid-area: aside;
  }
  .main {
    grid-area: main;
  }
  .aside[data-sticky] {
    position: sticky;
    top: var(--v4-detail-layout-offset);
  }
}

.truncate {
  display: inline-block;
  position: relative;
  width: 100%;
  min-width: 0;
  overflow: hidden;
  white-space: nowrap;
  vertical-align: bottom;
}
.mono {
  font-family: var(--v4-font-mono, monospace);
}
.measure {
  position: absolute;
  width: max-content;
  visibility: hidden;
  pointer-events: none;
  inset-inline-start: 0;
}
.collapse {
  display: block;
}
.collapse[hidden] {
  display: none;
}
.collapseInner {
  min-height: 0;
}
.text {
  margin: 0;
  color: var(--v4-ink, var(--foreground));
  font-family: var(--v4-type-body-font-family);
  font-size: var(--v4-type-body-font-size);
  line-height: var(--v4-type-body-line-height);
  font-weight: var(--v4-type-body-font-weight);
  letter-spacing: var(--v4-type-body-letter-spacing);
}
.small {
  margin: 0;
  color: var(--v4-text2, var(--muted-foreground));
  font-family: var(--v4-type-small-font-family);
  font-size: var(--v4-type-small-font-size);
  line-height: var(--v4-type-small-line-height);
  font-weight: var(--v4-type-small-font-weight);
  letter-spacing: var(--v4-type-small-letter-spacing);
}
.muted {
  color: var(--v4-muted, var(--muted-foreground));
}
.measurePage {
  width: 100%;
  max-width: var(--v4-size-measure-page);
  margin-inline: auto;
  padding: var(--v4-space-content-section) var(--v4-space-40);
}
.measureForm {
  width: 100%;
  max-width: var(--v4-size-measure-form);
}
@media (max-width: 640px) {
  .measurePage {
    padding: var(--v4-space-20) var(--v4-space-16);
  }
}
.stack {
  display: flex;
  flex-direction: column;
  min-width: 0;
}
.inline {
  display: flex;
  min-width: 0;
}
.grid {
  display: grid;
  min-width: 0;
}
.stack > *,
.inline > *,
.grid > * {
  min-width: 0;
}
.gridSplit {
  container-type: inline-size;
}
.gridSplit > * {
  grid-column: 1 / -1;
}
/* Container conditions cannot read custom properties, so this repeats size-sidecar-collapse (896px), the two-column breakpoint DetailLayout uses. */
@container (min-width: 896px) {
  .gridSplit > * {
    grid-column: auto;
  }
}
.container {
  width: 100%;
  min-width: 0;
  margin-inline: auto;
  max-width: var(--v4-size-measure-page);
}
.measureProse {
  width: 100%;
  min-width: 0;
  max-width: var(--v4-size-measure-prose);
}
.heading {
  margin: 0;
  color: var(--v4-ink, var(--foreground));
  font-family: var(--v4-heading-family);
  font-size: var(--v4-heading-size);
  line-height: var(--v4-heading-line);
  font-weight: var(--v4-heading-weight);
  letter-spacing: var(--v4-heading-tracking);
  overflow-wrap: anywhere;
  text-wrap: balance;
}
.heading[data-size="page"] {
  --v4-heading-family: var(--v4-type-title-lg-font-family);
  --v4-heading-size: var(--v4-type-title-lg-font-size);
  --v4-heading-line: var(--v4-type-title-lg-line-height);
  --v4-heading-weight: var(--v4-type-title-lg-font-weight);
  --v4-heading-tracking: var(--v4-type-title-lg-letter-spacing);
}
.heading[data-size="display"] {
  --v4-heading-family: var(--v4-type-display-font-family);
  --v4-heading-size: var(--v4-type-display-font-size);
  --v4-heading-line: var(--v4-type-display-line-height);
  --v4-heading-weight: var(--v4-type-display-font-weight);
  --v4-heading-tracking: var(--v4-type-display-letter-spacing);
}
.heading[data-size="section"] {
  --v4-heading-family: var(--v4-type-title-font-family);
  --v4-heading-size: var(--v4-type-title-font-size);
  --v4-heading-line: var(--v4-type-title-line-height);
  --v4-heading-weight: var(--v4-type-title-font-weight);
  --v4-heading-tracking: var(--v4-type-title-letter-spacing);
}
.heading[data-size="subsection"] {
  --v4-heading-family: var(--v4-type-title-sm-font-family);
  --v4-heading-size: var(--v4-type-title-sm-font-size);
  --v4-heading-line: var(--v4-type-title-sm-line-height);
  --v4-heading-weight: var(--v4-type-title-sm-font-weight);
  --v4-heading-tracking: var(--v4-type-title-sm-letter-spacing);
}
.meta {
  font-family: var(--v4-type-caption-font-family);
  font-size: var(--v4-type-caption-font-size);
  line-height: var(--v4-type-caption-line-height);
  font-weight: var(--v4-type-caption-font-weight);
  letter-spacing: var(--v4-type-caption-letter-spacing);
  font-variant-numeric: tabular-nums;
  color: var(--v4-muted, var(--muted-foreground));
}
.meta.mono {
  font-family: var(--v4-type-mono-sm-font-family);
  font-size: var(--v4-type-mono-sm-font-size);
  line-height: var(--v4-type-mono-sm-line-height);
  font-weight: var(--v4-type-mono-sm-font-weight);
  letter-spacing: var(--v4-type-mono-sm-letter-spacing);
}
.status {
  display: inline-flex;
  align-items: center;
  gap: var(--v4-space-6);
  min-width: 0;
  vertical-align: top;
  color: var(--v4-text2, var(--muted-foreground));
}
.status > svg {
  flex: none;
  width: var(--v4-size-icon);
  height: var(--v4-size-icon);
  stroke-width: var(--v4-stroke-icon);
}
.status[data-tone="ok"] {
  color: var(--v4-ok);
}
.status[data-tone="warn"] {
  color: var(--v4-warn);
}
.status[data-tone="bad"] {
  color: var(--v4-bad);
}
.highlight {
  background-color: var(--v4-accent);
  color: var(--v4-on-accent);
}
